	settingspb.UnimplementedSettingsServiceServer
	Store store.SettingsStore
}

func (s *SettingsServer) GetDisplaySettings(ctx context.Context, req *settingspb.GetDisplayRequest) (*settingspb.DisplayResponse, error) {
