corrected_code:
package settings

import (
	"context"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	settingspb "myapp/gen/settings/v1"
	"myapp/auth"
	"myapp/store"
)

type SettingsServer struct {
	settingspb.UnimplementedSettingsServiceServer
	Store store.SettingsStore
}

func (s *SettingsServer) GetDisplaySettings(ctx context.Context, req *settingspb.GetDisplayRequest) (*settingspb.DisplayResponse, error) {
	caller, ok := auth.UserFromContext(ctx)
	if !ok {
		return nil, status.Error(codes.Unauthenticated, "Authentication required")
	}

	if caller.ID != req.GetTargetUserId() && !caller.IsAdmin {
		return nil, status.Error(codes.PermissionDenied, "Unauthorized to view another user's display settings")
	}

	cfg, err := s.Store.FetchDisplay(ctx, req.GetTargetUserId())
	if err != nil {
		return nil, status.Errorf(codes.NotFound, "Settings not found: %v", err)
	}

	return &settingspb.DisplayResponse{
		Theme:        cfg.Theme,
		LanguageCode: cfg.LanguageCode,
		Density:      cfg.Density,
	}, nil
}
